python
def recursiveShelvesPositiveInkInvoice(readings):
    a=readings
    out=[]
    def visit(left,right):
        if left>=right: return
        out.append(sum(a[left:right]))
        if right-left>1:
            mid=(left+right)//2
            visit(left,mid)
            visit(mid,right)
    visit(0,len(a))
    return sum(x for x in out if x>0)


java
class Solution {
  public int recursiveShelvesPositiveInkInvoice(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {class Walk {void visit(int l,int r){if(l>=r)return;int s=0;for(int i=l;i<r;i++)s+=a[i];out.add(s);if(r-l>1){int m=(l+r)/2;visit(l,m);visit(m,r);}}}new Walk().visit(0,a.length);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
